#include <bits/stdc++.h>
using namespace std;
class Solution {public:int countSymmetricIntegers(int low,int high){int ans=0;for(int x=low;x<=high;++x){string s=to_string(x);if(s.size()%2)continue;int a=0,b=0;for(int i=0;i<(int)s.size()/2;++i){a+=s[i]-'0';b+=s[i+s.size()/2]-'0';}ans+=a==b;}return ans;}};
